const lista = ($('Gmail: nowe wiadomości').first().json.messages) || [];
const znane = {};
$('Już obsłużone wiadomości').all().forEach(function (i) { if (i.json && i.json.message_id) znane[i.json.message_id] = true; });
const nowe = lista.filter(function (m) { return !znane[m.id]; });
if (!nowe.length) return [];
const m = nowe[nowe.length - 1];
return [{ json: { id: m.id, threadId: m.threadId, zostalo: nowe.length - 1 } }];

const msg = $input.first().json;
const T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const zB64 = function (s) { s = String(s || '').replace(/-/g, '+').replace(/_/g, '/').replace(/[^A-Za-z0-9+\/]/g, ''); const o = []; let bufor = 0, bity = 0; for (let i = 0; i < s.length; i++) { bufor = (bufor << 6) | T.indexOf(s[i]); bity += 6; if (bity >= 8) { bity -= 8; o.push((bufor >> bity) & 255); } } return o; };
const zUtf8 = function (b) { let s = ''; for (let i = 0; i < b.length; i++) { const c = b[i]; if (c < 128) s += String.fromCharCode(c); else if (c >= 192 && c < 224) { s += String.fromCharCode(((c & 31) << 6) | (b[++i] & 63)); } else if (c >= 224 && c < 240) { s += String.fromCharCode(((c & 15) << 12) | ((b[++i] & 63) << 6) | (b[++i] & 63)); } else if (c >= 240) { let cp = ((c & 7) << 18) | ((b[++i] & 63) << 12) | ((b[++i] & 63) << 6) | (b[++i] & 63); cp -= 65536; s += String.fromCharCode(55296 + (cp >> 10), 56320 + (cp & 1023)); } } return s; };
const naglowki = {};
(((msg.payload || {}).headers) || []).forEach(function (h) { naglowki[h.name.toLowerCase()] = h.value; });
let tekst = '', html = '', raport = '';
const przejdz = function (p) {
  if (!p) return;
  const typ = String(p.mimeType || '').toLowerCase();
  if (p.body && p.body.data) {
    const t = zUtf8(zB64(p.body.data));
    if (typ === 'text/plain' && !tekst) tekst = t;
    else if (typ === 'text/html' && !html) html = t;
    else if (typ.indexOf('delivery-status') !== -1) raport += t;
  }
  (p.parts || []).forEach(przejdz);
};
przejdz(msg.payload);
if (!tekst && html) tekst = html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/[ \t]+/g, ' ');
if (!tekst) tekst = msg.snippet || '';
const odKogo = naglowki.from || '';
const adres = ((odKogo.match(/<([^>]+)>/) || [])[1] || odKogo).trim().toLowerCase();
const temat = naglowki.subject || '';
const nowaCzesc = tekst.split(/\n(?:>|On .+wrote:|W dniu .+napisał|-----Original|-----Oryginalna|Od: )/)[0].trim().slice(0, 3000);
const jestBounce = /mailer-daemon|postmaster|mail delivery/i.test(odKogo) || /(delivery status notification|undeliver|niedostarcz|nie można dostarczyć|returned mail|delivery failure|address not found)/i.test(temat);
let zlyAdres = (naglowki['x-failed-recipients'] || '').split(',')[0].trim().toLowerCase();
if (jestBounce && !zlyAdres) {
  const kandydaci = (String(raport + ' ' + tekst).match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi) || []).map(function (e) { return e.toLowerCase(); }).filter(function (e) { return !/mailer-daemon|postmaster|mrozikdigital@gmail\.com|googlemail|google\.com/.test(e); });
  zlyAdres = kandydaci[0] || '';
}
const twardy = jestBounce && !/(mailbox full|skrzynka.*pełna|over quota|temporar|tymczasow|try again later)/i.test(raport + ' ' + tekst);
return [{ json: { message_id: msg.id, thread_id: msg.threadId, rfc_id: naglowki['message-id'] || '', od: odKogo, adres: adres, domena: adres.split('@')[1] || '', temat: temat, tresc: nowaCzesc, bounce: jestBounce, twardy_bounce: twardy, zly_adres: zlyAdres, data: $now.toISO() } }];

const m = $('Odczytaj wiadomość').first().json;
const pierwszy = function (n) { const r = $(n).all().map(function (i) { return i.json; }).filter(function (x) { return x && x.id; }); return r[0] || null; };
const firma = pierwszy('Firma z tego wątku') || pierwszy('Firma z tym adresem') || (m.bounce ? null : pierwszy('Firma z tej domeny'));
let rodzaj = 'obca';
if (m.bounce && firma) rodzaj = m.twardy_bounce ? 'bounce' : 'obca';
else if (!m.bounce && firma) rodzaj = 'odpowiedz';
return [{ json: { rodzaj: rodzaj, firma: firma, wiadomosc: m } }];

const d = $input.first().json;
const instrukcja = [
  'Klasyfikujesz odpowiedź firmy na mail z propozycją współpracy (automatyzacje AI) wysłany przez Phillipa Mrozika.',
  'Kategorie:',
  '- zainteresowany: firma chce wiedzieć więcej, prosi o analizę, pyta o cenę, szczegóły, termin rozmowy lub zadaje jakiekolwiek pytanie o ofertę.',
  '- nie_teraz: teraz nie, ale nie zamyka tematu (brak czasu, inny termin, odezwijcie się później, może w przyszłości).',
  '- odmowa: wyraźne nie, nie jesteśmy zainteresowani, proszę nie pisać, wypisz mnie, zgłoszenie spamu, irytacja.',
  '- autoresponder: automatyczna odpowiedź (urlop, nieobecność, potwierdzenie otrzymania, zgłoszenie przyjęte, zmiana adresu).',
  'W razie wątpliwości między zainteresowany a nie_teraz wybierz zainteresowany. Między nie_teraz a odmowa wybierz odmowa.',
  'streszczenie: jedno proste zdanie po polsku, co napisała firma.',
  'powrot_dni: tylko dla autorespondera z datą powrotu - za ile dni od dziś osoba wraca (0 gdy brak daty). Dla innych kategorii 0.'
].join('\n');
const dane = { temat: d.wiadomosc.temat, od: d.wiadomosc.od, tresc: d.wiadomosc.tresc, dzisiaj: $now.toFormat('yyyy-MM-dd') };
const schemat = { type: 'object', additionalProperties: false, required: ['kategoria', 'streszczenie', 'powrot_dni'], properties: { kategoria: { type: 'string', enum: ['zainteresowany', 'nie_teraz', 'odmowa', 'autoresponder'] }, streszczenie: { type: 'string' }, powrot_dni: { type: 'integer' } } };
return [{ json: { zapytanie: { model: 'gpt-5.5', reasoning: { effort: 'low' }, input: [{ role: 'system', content: instrukcja }, { role: 'user', content: JSON.stringify(dane) }], text: { format: { type: 'json_schema', name: 'klasyfikacja', strict: true, schema: schemat } } } } }];

const d = $('Dopasuj do firmy').first().json;
let tekst = '';
(($input.first().json.output) || []).forEach(function (o) { if (o.type === 'message') (o.content || []).forEach(function (c) { if (c.type === 'output_text') tekst = c.text; }); });
if (!tekst) throw new Error('AI nie oceniło odpowiedzi');
const k = JSON.parse(tekst);
const f = d.firma;
const teraz = $now.setZone('Europe/Warsaw');
let status = f.status, dataNast = f.data_nastepnego || null;
if (k.kategoria === 'zainteresowany') { status = 'zainteresowany'; dataNast = null; }
if (k.kategoria === 'nie_teraz') { status = 'nie_teraz'; dataNast = teraz.plus({ days: 75 }).set({ hour: 8, minute: 10 }).toISO(); }
if (k.kategoria === 'odmowa') { status = 'odmowa'; dataNast = null; }
if (k.kategoria === 'autoresponder' && f.status === 'wyslana') { dataNast = teraz.plus({ days: Math.max(5, (k.powrot_dni || 0) + 1) }).set({ hour: 8, minute: 20 }).toISO(); }
const publiczna = /^(gmail|googlemail|wp|o2|onet|op|interia|vp|tlen|outlook|hotmail|live|icloud|yahoo|gazeta|int|buziaczek|go2)\.(pl|com|eu)$|^poczta\.(onet|fm)\.pl$/i.test(d.wiadomosc.domena);
return [{ json: { kategoria: k.kategoria, streszczenie: k.streszczenie, firma: f, wiadomosc: d.wiadomosc, aktualizacja: { status: status, kategoria_odpowiedzi: k.kategoria, data_nastepnego: dataNast }, blokuj: k.kategoria === 'odmowa' ? [String(f.email || d.wiadomosc.adres).toLowerCase()].concat(publiczna || !d.wiadomosc.domena ? [] : [d.wiadomosc.domena]) : [] } }];

const p = $('Zaplanuj reakcję').first().json;
const ikona = p.kategoria === 'odmowa' ? '🚫 Odmowa' : '⏳ Nie teraz';
const dopisek = p.kategoria === 'odmowa' ? 'Adres trafił na czarną listę, system już tam nie napisze.' : 'System odezwie się sam za ok. 2,5 miesiąca.';
return [{ json: { tekst: ikona + ': ' + p.firma.nazwa + ' (' + p.firma.miasto + ')\n' + p.streszczenie + '\n' + dopisek } }];

const p = $('Zaplanuj reakcję').first().json;
const r = $input.first().json || {};
let dane = {};
try { dane = typeof r.dane === 'string' ? JSON.parse(r.dane) : (r.dane || {}); } catch (e) { dane = {}; }
const instrukcja = [
  'Piszesz w imieniu Phillipa Mrozika (MrozikDigital) odpowiedź do firmy, która zainteresowała się propozycją automatyzacji AI. Phillip sprawdzi ten szkic i sam go wyśle.',
  'Najpierw krótko i konkretnie odnieś się do tego, co firma napisała (jeśli zadała pytanie, odpowiedz na nie; o cenę: napisz, że zależy od zakresu, a dzięki budowaniu portfolio będzie wyraźnie niżej niż standardowo, i że podasz konkretną kwotę po krótkiej rozmowie - bez wymyślania liczb).',
  'Potem MINI-ANALIZA dla tej firmy: 3 konkretne pomysły na automatyzacje, każdy w formie: tytuł, 1-2 proste zdania jak to działa, co firma zyska (czas, klienci lub pieniądze). Oprzyj się na danych z researchu i na tym, co firma napisała. Nie wymyślaj faktów o firmie. Nigdy nie proponuj strony internetowej, SEO ani marketingu.',
  'Na końcu zaproponuj krótką rozmowę (15 minut, telefon lub online) i zapytaj, kiedy im pasuje. Bez linku do kalendarza.',
  'Język: polski, per Państwo, bardzo prosty, bez słów technicznych (workflow, integracja, API, n8n, CRM, chatbot), bez wykrzykników i emotikon, bez długich myślników. Bez podpisu (zostanie dodany).'
].join('\n');
const wejscie = { odpowiedz_firmy: p.wiadomosc.tresc, firma: { nazwa: p.firma.nazwa, branza: p.firma.branza, miasto: p.firma.miasto }, nasz_pierwszy_mail: String(p.firma.tresc || '').slice(0, 1500), pomysl_glowny: p.firma.pomysl_glowny, pomysl_ekstra: p.firma.pomysl_ekstra, research: JSON.stringify(dane).slice(0, 9000) };
const schemat = { type: 'object', additionalProperties: false, required: ['tresc', 'pomysly_krotko'], properties: { tresc: { type: 'string' }, pomysly_krotko: { type: 'array', items: { type: 'string' } } } };
return [{ json: { zapytanie: { model: 'gpt-5.5', reasoning: { effort: 'medium' }, input: [{ role: 'system', content: instrukcja }, { role: 'user', content: JSON.stringify(wejscie) }], text: { format: { type: 'json_schema', name: 'mini_analiza', strict: true, schema: schemat } } } } }];

const utf8 = function (s) { const o = []; for (let i = 0; i < s.length; i++) { let c = s.charCodeAt(i); if (c < 128) o.push(c); else if (c < 2048) o.push(192 | (c >> 6), 128 | (c & 63)); else if (c >= 55296 && c < 56320) { const c2 = s.charCodeAt(++i); const cp = 65536 + ((c - 55296) << 10) + (c2 - 56320); o.push(240 | (cp >> 18), 128 | ((cp >> 12) & 63), 128 | ((cp >> 6) & 63), 128 | (cp & 63)); } else o.push(224 | (c >> 12), 128 | ((c >> 6) & 63), 128 | (c & 63)); } return o; };
const b64 = function (b) { const T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'; let o = ''; for (let i = 0; i < b.length; i += 3) { const x = b[i], y = b[i + 1], z = b[i + 2]; o += T[x >> 2] + T[((x & 3) << 4) | ((y === undefined ? 0 : y) >> 4)] + (y === undefined ? '=' : T[((y & 15) << 2) | ((z === undefined ? 0 : z) >> 6)]) + (z === undefined ? '=' : T[z & 63]); } return o; };
const ascii = function (s) { const o = []; for (let i = 0; i < s.length; i++) o.push(s.charCodeAt(i) & 255); return o; };
const zbudujMime = function (do_, temat, tresc, odpowiedzNa) {
  const linie = ['From: Phillip Mrozik <mrozikdigital@gmail.com>', 'To: ' + do_, 'Subject: =?UTF-8?B?' + b64(utf8(temat)) + '?=', 'MIME-Version: 1.0', 'Content-Type: text/plain; charset="UTF-8"', 'Content-Transfer-Encoding: base64'];
  if (odpowiedzNa) { linie.push('In-Reply-To: ' + odpowiedzNa); linie.push('References: ' + odpowiedzNa); }
  const cialo = b64(utf8(tresc)).replace(/(.{76})/g, '$1\r\n');
  return b64(ascii(linie.join('\r\n') + '\r\n\r\n' + cialo)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
};
const p = $('Zaplanuj reakcję').first().json;
let t = '';
((($input.first().json) || {}).output || []).forEach(function (o) { if (o.type === 'message') (o.content || []).forEach(function (c) { if (c.type === 'output_text') t = c.text; }); });
let wynik = { tresc: '', pomysly_krotko: [] };
try { wynik = JSON.parse(t); } catch (e) {}
let tresc = String(wynik.tresc || '').trim().replace(/\n*(pozdrawiam|z pozdrowieniami)[\s\S]*$/i, '').trim().replace(/ — /g, ', ');
const awaria = !tresc;
if (awaria) tresc = 'Dzień dobry,\n\ndziękuję za odpowiedź. Chętnie przygotuję krótką analizę z konkretnymi pomysłami dla Państwa firmy. Czy pasowałaby krótka, 15-minutowa rozmowa w tym tygodniu?';
tresc += '\n\nPozdrawiam\nPhillip Mrozik\nMrozikDigital | 787 957 534\nhttps://www.mrozikdigital.com';
const temat = /^re:/i.test(p.wiadomosc.temat) ? p.wiadomosc.temat : 'Re: ' + (p.wiadomosc.temat || 'Propozycja współpracy');
return [{ json: { awaria: awaria, pomysly: wynik.pomysly_krotko || [], tresc: tresc, cialo: { message: { raw: zbudujMime(p.wiadomosc.od || p.wiadomosc.adres, temat, tresc, p.wiadomosc.rfc_id), threadId: p.wiadomosc.thread_id } } } }];

const p = $('Zaplanuj reakcję').first().json;
const s = $('Złóż szkic odpowiedzi').first().json;
const okSzkic = !!($input.first().json || {}).id;
const linie = [
  '🔥 Firma zainteresowana!',
  p.firma.nazwa + ' (' + p.firma.branza + ', ' + p.firma.miasto + ')',
  'Od: ' + p.wiadomosc.adres + (p.firma.telefon ? ' | tel. ' + p.firma.telefon : ''),
  '',
  'Napisali: ' + p.streszczenie,
  '',
  okSzkic ? '✍️ Szkic odpowiedzi z mini-analizą czeka w Gmailu (Wersje robocze) w tym samym wątku. Sprawdź i wyślij.' : '⚠️ Nie udało się utworzyć szkicu w Gmailu, odpisz ręcznie.'
];
if (s.pomysly && s.pomysly.length) linie.push('', 'Pomysły w analizie:', s.pomysly.map(function (x) { return '• ' + x; }).join('\n'));
linie.push('', 'https://mail.google.com/mail/u/0/#inbox/' + p.wiadomosc.thread_id);
return [{ json: { tekst: linie.join('\n') } }];

const w = $input.all().map(function (i) { return i.json; }).filter(function (x) { return x && x.id; });
const odbite = w.filter(function (x) { return x.status === 'odbity'; }).length;
if (odbite < 4) return [];
return [{ json: { odbite: odbite, razem: w.length, tekst: '🛑 Wysyłka zatrzymana automatycznie.\n' + odbite + ' z ostatnich ' + w.length + ' maili wróciło jako niedostarczone. To może zaszkodzić reputacji skrzynki.\nSprawdź adresy, a potem wznów system w panelu (Stan systemu i sterowanie).' } }];

const r = function (n) { return $(n).all().map(function (i) { return i.json; }).filter(function (x) { return x && x.id; }); };
const ust = {}; r('Raport: ustawienia').forEach(function (u) { ust[u.klucz] = u.wartosc; });
const w = r('Raport: dzisiejsze wysyłki');
const o = r('Raport: dzisiejsze odpowiedzi').filter(function (x) { return x.kategoria !== 'niezwiazana' && x.kategoria !== 'zwrot_inny'; });
const licz = function (arr, pole, war) { return arr.filter(function (x) { return x[pole] === war; }).length; };
const nowe = r('Raport: firmy przebadane dziś');
const kamp = r('Raport: kampanie').filter(function (k) { return k.status === 'aktywna'; });
const fc = $('Firecrawl: stan kredytów').first().json || {};
const kredyty = ((fc.data || {}).remainingCredits);
const gotowe = r('Raport: gotowe maile').length;
const linie = [
  '📊 Raport dnia ' + $now.setZone('Europe/Warsaw').toFormat('dd.MM.yyyy') + (ust.tryb_testowy !== 'nie' ? ' (TRYB TESTOWY)' : ''),
  '',
  '📤 Wysłane: ' + w.filter(function (x) { return x.status !== 'odbity'; }).length + ' (pierwsze: ' + licz(w, 'typ', 'pierwszy') + ', follow-upy: ' + (licz(w, 'typ', 'followup1') + licz(w, 'typ', 'followup2') + licz(w, 'typ', 'powrot')) + ')',
  '↩️ Zwroty: ' + licz(w, 'status', 'odbity'),
  '💬 Odpowiedzi: ' + o.length + ' (zainteresowani: ' + licz(o, 'kategoria', 'zainteresowany') + ', nie teraz: ' + licz(o, 'kategoria', 'nie_teraz') + ', odmowy: ' + licz(o, 'kategoria', 'odmowa') + ', automaty: ' + licz(o, 'kategoria', 'autoresponder') + ')',
  '',
  '🔎 Research od wczoraj: gotowe ' + licz(nowe, 'status', 'gotowa') + ', odrzucone ' + licz(nowe, 'status', 'odrzucona'),
  '📦 Gotowe maile w kolejce: ' + gotowe + ' (na ok. ' + Math.floor(gotowe / Math.max(1, parseInt(ust.limit_dzienny || '30', 10))) + ' dni)',
  '🎯 Aktywne kampanie: ' + (kamp.length ? kamp.map(function (k) { return k.branza + ' – ' + k.miasto; }).join(', ') : 'brak, dodaj nową w panelu'),
  '🔥 Firecrawl: ' + (typeof kredyty === 'number' ? kredyty + ' kredytów' : 'nie udało się sprawdzić'),
  ust.system_wstrzymany === 'tak' ? '\n⏸️ System jest WSTRZYMANY.' : ''
];
return [{ json: { tekst: linie.join('\n').trim() } }];

const r = function (n) { return $(n).all().map(function (i) { return i.json; }).filter(function (x) { return x && x.id; }); };
const maile = r('Pierwsze maile z 30 dni').filter(function (m) { return !m.tryb_testowy; });
const odp = r('Odpowiedzi z 30 dni');
if (maile.length < 15) return [{ json: { pomin: true, tekst: '🧠 Wnioski tygodnia: za mało prawdziwych wysyłek (' + maile.length + '), żeby wyciągać wnioski. Spróbuję za tydzień.' } }];
const kat = {}; odp.forEach(function (o) { if (o.firma_id) kat[o.firma_id] = o.kategoria; });
const proba = maile.map(function (m) { return { wynik: kat[m.firma_id] || 'brak_odpowiedzi', tresc: String(m.tresc || '').replace(/Pozdrawiam[\s\S]*$/, '').slice(0, 900) }; });
const dobre = proba.filter(function (p) { return p.wynik === 'zainteresowany'; }).slice(0, 15);
const zle = proba.filter(function (p) { return p.wynik === 'odmowa'; }).slice(0, 10);
const cisza = proba.filter(function (p) { return p.wynik === 'brak_odpowiedzi'; }).slice(0, 15);
const instrukcja = [
  'Analizujesz skuteczność cold maili Phillipa Mrozika (propozycje automatyzacji AI dla polskich firm). Dostajesz maile, na które firmy odpowiedziały z zainteresowaniem, odmówiły albo nie odpowiedziały.',
  'Napisz zwięzłe wnioski dla autora kolejnych maili: maksymalnie 6 krótkich punktów, łącznie do 700 znaków. Tylko rzeczy poparte danymi (np. jakie tematy, otwarcia, długość, ton działały lepiej). Jeśli danych jest mało, napisz mniej punktów.',
  'Wnioski NIE mogą łamać stałych zasad: temat Propozycja współpracy, prosty język, wyrażenie automatyzacja AI dokładnie raz, zdanie o niższej cenie przez portfolio, pytanie o darmową analizę, link do realizacji, zakaz proponowania stron internetowych, zakaz wymyślania faktów.',
  'Dodaj też podsumowanie_dla_phillipa: 2-4 proste zdania po polsku, co działa, a co nie.'
].join('\n');
const dane = { liczby: { wyslane: maile.length, zainteresowani: dobre.length, odmowy: proba.filter(function (p) { return p.wynik === 'odmowa'; }).length, bez_odpowiedzi: proba.filter(function (p) { return p.wynik === 'brak_odpowiedzi'; }).length }, obecne_wnioski: ($('Obecne wnioski').first().json || {}).wartosc || '', zainteresowani: dobre, odmowy: zle, bez_odpowiedzi: cisza };
const schemat = { type: 'object', additionalProperties: false, required: ['wnioski', 'podsumowanie_dla_phillipa'], properties: { wnioski: { type: 'string' }, podsumowanie_dla_phillipa: { type: 'string' } } };
